    var options = {
        uri: endpoints.registerUrl,
        method: 'POST',
        json: true,
        body: req.body
    };

    console.log("Posting Customer: " + JSON.stringify(req.body));

    async.waterfall([
            function(callback) {
                request(options, function(error, response, body) {
                    if (error !== null ) {
                        callback(error);
                        return;
                    }
                    if (response.statusCode == 200 && body != null && body != "") {
                        if (body.error) {
                            callback(body.error);
                            return;
                        }
                        console.log(body);
                        var customerId = body.id;
                        console.log(customerId);
                        req.session.customerId = customerId;
                        callback(null, customerId);
                        return;
                    }
                    console.log(response.statusCode);
                    callback(true);
                });
            },
            function(custId, callback) {
                var sessionId = req.session.id;
                console.log("Merging carts for customer id: " + custId + " and session id: " + sessionId);

                var options = {
                    uri: endpoints.cartsUrl + "/" + custId + "/merge" + "?sessionId=" + sessionId,
                    method: 'GET'
                };
                request(options, function(error, response, body) {
                    if (error) {
                        if(callback) callback(error);
                        return;
                    }
                    console.log('Carts merged.');
                    if(callback) callback(null, custId);
                });
            }
        ],
        function(err, custId) {
            if (err) {
                console.log("Error with log in: " + err);
                res.status(500);
                res.end();
                return;
            }
            console.log("set cookie" + custId);
            res.status(200);
            res.cookie(cookie_name, req.session.id, {
                maxAge: 3600000
            }).send({id: custId});
            console.log("Sent cookies.");
            res.end();
            return;
        }
    );
});

@RequestMapping(value = "/{customerId}/merge", method = RequestMethod.GET)
public void mergeCarts(@PathVariable String customerId, @RequestParam(value = "sessionId") String sessionId) {
    logger.debug("Merge carts request received for ids: " + customerId + " and " + sessionId);
    CartResource sessionCart = new CartResource(cartDAO, sessionId);
    CartResource customerCart = new CartResource(cartDAO, customerId);
    customerCart.merge(sessionCart.value().get()).run();
    delete(sessionId);
}

